// ---- Pick reviews that still need a Claude label and build requests ----
const DEFAULT_MODEL = 'claude-haiku-5-5';
const BATCH = 25;
const CHUNK = 400;        // reviews per loop; each loop is saved before the next starts (checkpoint)
const MAX_LOOPS = 10;     // safety guard: never loop forever
const loop = $runIndex;   // 0 on first pass, 1 on second, ...

const cfg = Object.fromEntries($('Read config').all(0, 0).map(i => [i.json.key, String(i.json.value ?? '')]));
const model = /\d/.test(cfg.tagging_model || '') ? cfg.tagging_model : DEFAULT_MODEL;
const themes = $('Read themes').all(0, 0).map(i => i.json).filter(t => String(t.active).toUpperCase() === 'TRUE');
const fees = $('Read fee_types').all(0, 0).map(i => i.json).filter(t => String(t.active).toUpperCase() === 'TRUE');
const reviews = $input.all().map(i => i.json);   // fresh read of the Sheet on every loop

// priority: base sample first (theme shares depend on it), then fee-boost rows; newest first within each
const isBase = r => r.sample_reason === 'top_upvoted' || r.sample_reason === 'random';
const todo = reviews
  .filter(r => r.review_id && r.theme_source !== 'claude_v1')
  .sort((a, b) => (isBase(b) - isBase(a)) || String(b.review_date).localeCompare(String(a.review_date)));
if (loop >= MAX_LOOPS) return [{ json: { nothing_to_tag: true, stopped_by_guard: true, loops: loop, remaining: todo.length } }];
const thisRun = todo.slice(0, CHUNK);

const themeText = themes.map(t => `- ${t.theme_code} (${t.theme_name}): ${t.definition}. Include: ${t.include_when}.${t.exclude_when ? ' Exclude: ' + t.exclude_when + '.' : ''}`).join('\n');
const feeText = fees.map(f => `- ${f.fee_code} (${f.label}): ${f.definition}. Users say things like: ${f.user_says_like}`).join('\n');

const system = `You label Google Play reviews of the ChatGPT Android app (India store) for a product team.
For every review return exactly one theme code and exactly one fee code.

THEMES
${themeText}

THEME RULES
1. Label the main complaint. If the review contains any clear complaint, do not use PRAISE, even if it also praises the app.
2. If there are several complaints, pick the one the user spends the most words on; if tied, the first one mentioned.
3. BILLING is only for payments, plan activation, cancellation, renewal or refunds. "Limits are too tight", "pushes me to upgrade" and "too expensive" are LIMITS.
4. UNCLEAR: text too short or vague to know what the user means ("nice", "bad app", "useless", gibberish), or comments not about using the app (e.g. AI harms the environment). Short generic praise such as "very useful for study" is PRAISE.
5. Image generation that is refused, inaccurate or changes faces is QUALITY. Image or attachment quotas are LIMITS. Login, crashes, lost chats, voice/read-aloud malfunctions and unwanted UI changes are BUGS.
6. Judge by the text; the star rating is only context.
7. Reviews may be in Hindi, Hinglish or other languages: understand them and label normally.

FEE CODES (use NONE unless the review clearly describes one of these situations)
${feeText}
- NONE: no money/plan confusion described.

OUTPUT
Return ONLY a JSON array, one object per review, in the same order as given:
[{"id":"<id>","theme":"<THEME_CODE>","fee":"<FEE_CODE or NONE>"}]
No commentary, no markdown fences.`;

if (!thisRun.length) return [{ json: { nothing_to_tag: true, stopped_by_guard: false, loops: loop, remaining: 0 } }];

const out = [];
for (let i = 0; i < thisRun.length; i += BATCH) {
  const chunk = thisRun.slice(i, i + BATCH);
  out.push({ json: {
    nothing_to_tag: false,
    batch_no: out.length + 1,
    ids: chunk.map(r => r.review_id),
    loop,
    remaining_after_chunk: todo.length - thisRun.length,
    request: { model, max_tokens: 4000, system, messages: [{ role: 'user', content:
      'Label these reviews:\n' + JSON.stringify(chunk.map(r => ({ id: r.review_id, rating: Number(r.rating), text: String(r.text).slice(0, 700) }))) }] }
  }});
}
return out;

// ---- Turn Claude replies into rows to write back (matched on review_id) ----
const batches = $('Select & build batches').all(0, $runIndex).map(i => i.json);   // same loop as this run
const themeCodes = new Set($('Read themes').all(0, 0).map(i => i.json.theme_code));
const feeCodes = new Set($('Read fee_types').all(0, 0).map(i => i.json.fee_code));
const rows = []; let parseErrors = 0, invalid = 0;

$input.all().forEach((item, idx) => {
  const ids = new Set(batches[idx]?.ids || []);
  const txt = (item.json.content || []).map(c => c.text || '').join('');
  const m = txt.match(/\[[\s\S]*\]/);
  let arr;
  try { arr = JSON.parse(m ? m[0] : txt); } catch (e) { parseErrors++; return; }  // batch stays untagged → retried next run
  for (const o of arr) {
    const id = String(o.id);
    if (!ids.has(id)) continue;
    let theme = String(o.theme || '').trim().toUpperCase();
    let fee = String(o.fee || 'NONE').trim().toUpperCase();
    if (!themeCodes.has(theme)) { invalid++; continue; }          // skip, retried next run
    if (!feeCodes.has(fee)) fee = '';
    rows.push({ review_id: id, theme_code: theme, fee_type: fee, theme_source: 'claude_v1' });
  }
});
if (!rows.length) throw new Error(`No usable labels. parse errors: ${parseErrors}, invalid: ${invalid}`);
return rows.map(r => ({ json: r }));

// ---- 10-week analysis for one run_id. All numbers are computed here, not by the AI. ----
const COMPLAINT = ['QUALITY', 'LIMITS', 'BUGS', 'BILLING'];
const FEE_ELIGIBLE = ['F_ACTIVATION', 'F_AUTORENEW', 'F_REFUND'];   // misunderstood charges (not price/limit complaints)
const MIN_COVERAGE = 0.95;

const cfg = Object.fromEntries($('Read config').all(0, 0).map(i => [i.json.key, String(i.json.value ?? '')]));
const windowWeeks = Number(cfg.window_weeks || 10);
const themes = Object.fromEntries($('Read themes').all(0, 0).map(i => [i.json.theme_code, i.json.theme_name]));
const fees = Object.fromEntries($('Read fee_types').all(0, 0).map(i => [i.json.fee_code, i.json.label]));
const reviews = $('Read reviews (fresh)').all(0, 0).map(i => i.json);

// --- which week? orchestrator passes run_id; manual runs use the last full ISO week (IST)
let runId = '';
try { runId = String($('When called by orchestrator').first().json.run_id || ''); } catch (e) {}
const isoWeek = d => { const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const day = t.getUTCDay() || 7; t.setUTCDate(t.getUTCDate() + 4 - day);
  const y = t.getUTCFullYear(); const w = Math.ceil(((t - Date.UTC(y, 0, 1)) / 864e5 + 1) / 7);
  return `${y}-W${String(w).padStart(2, '0')}`; };
const mondayOf = id => { const [y, w] = id.split('-W').map(Number); const jan4 = new Date(Date.UTC(y, 0, 4));
  const d = new Date(jan4); d.setUTCDate(jan4.getUTCDate() - ((jan4.getUTCDay() || 7) - 1) + (w - 1) * 7); return d; };
if (!/^\d{4}-W\d{2}$/.test(runId)) {
  const nowIst = new Date(Date.now() + 5.5 * 3600e3);
  runId = isoWeek(new Date(nowIst.getTime() - 7 * 864e5));
}
const weekStart = mondayOf(runId);
const fmt = d => d.toISOString().slice(0, 10);
const weeks = Array.from({ length: windowWeeks }, (_, k) => isoWeek(new Date(weekStart.getTime() - (windowWeeks - 1 - k) * 7 * 864e5)));
const wset = new Set(weeks);

const inWin = reviews.filter(r => wset.has(r.week_id));
const base = inWin.filter(r => r.sample_reason === 'top_upvoted' || r.sample_reason === 'random');
const tagged = base.filter(r => r.theme_source === 'claude_v1' && r.theme_code);
const coverage = base.length ? tagged.length / base.length : 0;
const coverageAll = inWin.length ? inWin.filter(r => r.theme_source === 'claude_v1').length / inWin.length : 0;
const thisWeek = tagged.filter(r => r.week_id === runId);

// --- theme stats
const stat = rows => {
  const by = {};
  for (const r of rows) {
    const t = r.theme_code; by[t] = by[t] || { n: 0, sumRating: 0, neg: 0 };
    by[t].n++; by[t].sumRating += Number(r.rating); if (Number(r.rating) <= 2) by[t].neg++;
  }
  return Object.fromEntries(Object.entries(by).map(([t, v]) => [t, {
    name: themes[t] || t, n: v.n, share: +(v.n / rows.length).toFixed(3),
    avg_rating: +(v.sumRating / v.n).toFixed(2), neg_share: +(v.neg / v.n).toFixed(2) }]));
};
const window = stat(tagged);
const week = thisWeek.length ? stat(thisWeek) : {};
const ranked = COMPLAINT.filter(t => window[t])
  .map(t => ({ code: t, score: +(window[t].n * window[t].neg_share).toFixed(1) }))
  .sort((a, b) => b.score - a.score);
const top3 = ranked.slice(0, 3).map(x => x.code);

// trend per top theme: share in last half of window vs first half
const half = Math.floor(windowWeeks / 2);
const early = new Set(weeks.slice(0, half)), late = new Set(weeks.slice(half));
const shareIn = (set, t) => { const rs = tagged.filter(r => set.has(r.week_id)); return rs.length ? rs.filter(r => r.theme_code === t).length / rs.length : 0; };
const trends = Object.fromEntries(top3.map(t => {
  const a = shareIn(early, t), b = shareIn(late, t), d = b - a;
  return [t, { early_share: +a.toFixed(3), late_share: +b.toFixed(3),
    direction: Math.abs(d) < 0.03 ? 'stable' : d > 0 ? 'rising' : 'falling',
    this_week_share: week[t]?.share ?? null }];
}));

// --- fee issue (all low-star rows incl. fee boost)
const feeRows = inWin.filter(r => r.theme_source === 'claude_v1' && FEE_ELIGIBLE.includes(r.fee_type) && Number(r.rating) <= 3);
const feeCount = {}; for (const r of feeRows) feeCount[r.fee_type] = (feeCount[r.fee_type] || 0) + 1;
const feeRank = Object.entries(feeCount).sort((a, b) => b[1] - a[1]);
const feeCode = feeRank[0]?.[0] || '';
const feeOf = (set) => feeRows.filter(r => r.fee_type === feeCode && set.has(r.week_id)).length;
const billingLow = set => inWin.filter(r => set.has(r.week_id) && String(r.fee_mention).toUpperCase() === 'TRUE' && Number(r.rating) <= 3).length;
const feeEarly = feeOf(early), feeLate = feeOf(late);
const feeEarlyShare = billingLow(early) ? feeEarly / billingLow(early) : 0;
const feeLateShare = billingLow(late) ? feeLate / billingLow(late) : 0;
const feeDirection = Math.abs(feeLateShare - feeEarlyShare) < 0.005 ? 'stable' : feeLateShare > feeEarlyShare ? 'rising' : 'falling';

// --- quote candidates: verbatim, specific, low-star, recent first
const words = s => String(s).trim().split(/\s+/).length;
const pick = (rows, n) => rows
  .filter(r => Number(r.rating) <= 2 && words(r.text) >= 10 && words(r.text) <= 60 && !/https?:\/\/|@\w+\.\w+|\b\d{10}\b/.test(r.text))
  .sort((a, b) => String(b.review_date).localeCompare(String(a.review_date)) || Number(b.thumbs_up) - Number(a.thumbs_up))
  .slice(0, n)
  .map(r => ({ review_id: r.review_id, date: String(r.review_date).slice(0, 10), rating: Number(r.rating), text: String(r.text).trim() }));
const quotes = {
  themes: Object.fromEntries(top3.map(t => [t, pick(tagged.filter(r => r.theme_code === t), 5)])),
  fee: pick(feeRows.filter(r => r.fee_type === feeCode), 5),
};

const status = (coverage >= MIN_COVERAGE && coverageAll >= MIN_COVERAGE) ? (feeCode ? 'analysed' : 'analysed_no_fee_issue') : 'tagging_in_progress';
const summary = {
  run_id: runId, week_start: fmt(weekStart), week_end: fmt(new Date(weekStart.getTime() + 6 * 864e5)),
  status, window_from: fmt(mondayOf(weeks[0])), window_to: fmt(new Date(weekStart.getTime() + 6 * 864e5)),
  base_n: tagged.length,
  theme_stats_json: JSON.stringify({ window, this_week: week, ranking: ranked, trends, coverage: +coverage.toFixed(3), coverage_all: +coverageAll.toFixed(3), this_week_n: thisWeek.length }),
  top_themes: top3.join(','),
  quotes_json: JSON.stringify(quotes),
  fee_code: feeCode,
  fee_count: feeCount[feeCode] || 0,
  fee_trend: feeCode ? `${feeEarly} -> ${feeLate} (${(feeEarlyShare * 100).toFixed(1)}% -> ${(feeLateShare * 100).toFixed(1)}% of low-star billing reviews), ${feeDirection}` : '',
  error: status === 'tagging_in_progress' ? `Tagged: base ${(coverage * 100).toFixed(0)}%, all ${(coverageAll * 100).toFixed(0)}% – run again to continue` : '',
  updated_at: new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 19),
};
return [{ json: summary }];
